<?php

declare(strict_types=1);

namespace Moves\Services\Talk;

use Moves\Boot\Connection;
use PDO;

final class TalkService
{
    public function __construct(private ?int $tenantId = null) {}
    private function tenantId(): int { return $this->tenantId ??= (new TalkTenantContext())->currentTenantId(); }
    private function notifications(): TalkNotificationService { return new TalkNotificationService($this->tenantId()); }

    public function dashboard(): array { $pdo=Connection::getInstance();$tenant=$this->tenantId();return ['counts'=>['queued'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_tickets WHERE tenant_id={$tenant} AND status='queued'"),'active'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_tickets WHERE tenant_id={$tenant} AND status IN ('assigned','open')"),'closed_today'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_tickets WHERE tenant_id={$tenant} AND status='closed' AND DATE(closed_at)=CURRENT_DATE"),'contacts'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_contacts WHERE tenant_id={$tenant}")],'queue'=>$this->queue()]; }
    public function queue(): array { $s=Connection::getInstance()->prepare("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.queued_at,t.created_at,c.name contact_name,c.phone contact_phone,q.name queue_name,u.name assigned_name,cv.channel FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id AND cv.tenant_id=t.tenant_id INNER JOIN talk_contacts c ON c.id=cv.contact_id AND c.tenant_id=t.tenant_id LEFT JOIN talk_queues q ON q.id=t.queue_id AND q.tenant_id=t.tenant_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.tenant_id=:tenant_id AND t.status='queued' ORDER BY FIELD(t.priority,'urgent','high','normal','low'),COALESCE(t.queued_at,t.created_at),t.id LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function heartbeat(int $userId): void { (new TalkTenantContext())->forUser($userId,$this->tenantId());Connection::getInstance()->prepare("INSERT INTO talk_presence(tenant_id,user_id,status,last_seen_at) VALUES(:tenant_id,:user_id,'online',NOW()) ON DUPLICATE KEY UPDATE status='online',last_seen_at=NOW()")->execute(['tenant_id'=>$this->tenantId(),'user_id'=>$userId]); }
    public function permissions(int $userId): array { $s=Connection::getInstance()->prepare("SELECT COALESCE(tus.talk_role,tu.role,'agent') talk_role,COALESCE(tus.max_active_tickets,5) max_active_tickets FROM talk_tenant_users tu LEFT JOIN talk_user_settings tus ON tus.tenant_id=tu.tenant_id AND tus.user_id=tu.user_id WHERE tu.tenant_id=:tenant_id AND tu.user_id=:id AND tu.status='active'");$s->execute(['tenant_id'=>$this->tenantId(),'id'=>$userId]);return $s->fetch(PDO::FETCH_ASSOC)?:['talk_role'=>'none','max_active_tickets'=>0]; }
    public function canManage(int $userId): bool { return in_array((string)($this->permissions($userId)['talk_role']??'agent'),['supervisor','admin'],true); }
    public function canOperateTicket(int $ticketId,int $userId): bool
    {
        $manage=$this->canManage($userId);
        $s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_tickets WHERE tenant_id=:tenant_id AND id=:id AND (:manage=1 OR (assigned_user_id=:user_id AND status IN ('assigned','open')))");
        $s->execute(['tenant_id'=>$this->tenantId(),'id'=>$ticketId,'manage'=>$manage?1:0,'user_id'=>$userId]);
        return (int)$s->fetchColumn()>0;
    }
    public function canViewTicket(int $ticketId,int $userId): bool { $manage=$this->canManage($userId);$s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_tickets t LEFT JOIN talk_queue_members qm ON qm.tenant_id=t.tenant_id AND qm.queue_id=t.queue_id AND qm.user_id=:queue_user_id AND qm.status='active' WHERE t.tenant_id=:tenant_id AND t.id=:id AND (:manage=1 OR t.assigned_user_id=:assigned_user_id OR (t.status='queued' AND qm.user_id IS NOT NULL))");$s->execute(['tenant_id'=>$this->tenantId(),'queue_user_id'=>$userId,'assigned_user_id'=>$userId,'id'=>$ticketId,'manage'=>$manage?1:0]);return (int)$s->fetchColumn()>0; }
    public function saveUserSettings(int $targetUserId,string $role,int $capacity): void { (new TalkTenantContext())->forUser($targetUserId,$this->tenantId());if(!in_array($role,['agent','supervisor','admin'],true))$role='agent';$capacity=max(1,min(100,$capacity));Connection::getInstance()->prepare("INSERT INTO talk_user_settings(tenant_id,user_id,talk_role,max_active_tickets) VALUES(:tenant_id,:user_id,:role,:capacity) ON DUPLICATE KEY UPDATE talk_role=VALUES(talk_role),max_active_tickets=VALUES(max_active_tickets)")->execute(['tenant_id'=>$this->tenantId(),'user_id'=>$targetUserId,'role'=>$role,'capacity'=>$capacity]); }
    public function saveQueue(int $id,string $name,?int $departmentId,int $seconds,string $status): int { $name=trim($name);if($name==='')throw new \RuntimeException('Informe o nome da fila.');$status=in_array($status,['active','inactive'],true)?$status:'active';$seconds=max(5,min(86400,$seconds));$slug=$this->slug($name);$pdo=Connection::getInstance();$tenant=$this->tenantId();if($departmentId!==null){$v=$pdo->prepare('SELECT COUNT(*) FROM talk_departments WHERE tenant_id=:tenant_id AND id=:id');$v->execute(['tenant_id'=>$tenant,'id'=>$departmentId]);if((int)$v->fetchColumn()===0)throw new \RuntimeException('Departamento inválido.');}if($id>0){$s=$pdo->prepare("UPDATE talk_queues SET name=:name,department_id=:department_id,auto_assign_after_seconds=:seconds,status=:status WHERE tenant_id=:tenant_id AND id=:id");$s->execute(['tenant_id'=>$tenant,'name'=>$name,'department_id'=>$departmentId,'seconds'=>$seconds,'status'=>$status,'id'=>$id]);if($s->rowCount()===0)throw new \RuntimeException('Fila não encontrada.');return $id;}$base=$slug;$n=2;while($this->queueSlugExists($slug))$slug=$base.'-'.$n++;$s=$pdo->prepare("INSERT INTO talk_queues(tenant_id,department_id,name,slug,status,auto_assign_after_seconds) VALUES(:tenant_id,:department_id,:name,:slug,:status,:seconds)");$s->execute(['tenant_id'=>$tenant,'department_id'=>$departmentId,'name'=>$name,'slug'=>$slug,'status'=>$status,'seconds'=>$seconds]);return (int)$pdo->lastInsertId(); }
    public function saveDepartment(int $id,string $name,string $status): int { $name=trim($name);if($name==='')throw new \RuntimeException('Informe o nome do departamento.');$status=in_array($status,['active','inactive'],true)?$status:'active';$pdo=Connection::getInstance();$tenant=$this->tenantId();$slug=$this->slug($name);if($id>0){$s=$pdo->prepare("UPDATE talk_departments SET name=:name,status=:status WHERE tenant_id=:tenant_id AND id=:id");$s->execute(['tenant_id'=>$tenant,'name'=>$name,'status'=>$status,'id'=>$id]);if($s->rowCount()===0)throw new \RuntimeException('Departamento não encontrado.');return $id;}$base=$slug;$n=2;while(true){$x=$pdo->prepare('SELECT COUNT(*) FROM talk_departments WHERE tenant_id=:tenant_id AND slug=:slug');$x->execute(['tenant_id'=>$tenant,'slug'=>$slug]);if((int)$x->fetchColumn()===0)break;$slug=$base.'-'.$n++;}$s=$pdo->prepare("INSERT INTO talk_departments(tenant_id,name,slug,status) VALUES(:tenant_id,:name,:slug,:status)");$s->execute(['tenant_id'=>$tenant,'name'=>$name,'slug'=>$slug,'status'=>$status]);return (int)$pdo->lastInsertId(); }
    public function departments(): array { $s=Connection::getInstance()->prepare("SELECT id,name,slug,status FROM talk_departments WHERE tenant_id=:tenant_id ORDER BY name");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function queueMembers(int $queueId): array { $s=Connection::getInstance()->prepare("SELECT qm.queue_id,qm.user_id,qm.role,qm.capacity,qm.status,u.name,u.email FROM talk_queue_members qm INNER JOIN users u ON u.id=qm.user_id WHERE qm.tenant_id=:tenant_id AND qm.queue_id=:id ORDER BY u.name");$s->execute(['tenant_id'=>$this->tenantId(),'id'=>$queueId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function saveQueueMember(int $queueId,int $userId,string $role,int $capacity,string $status): void { if(!in_array($role,['agent','supervisor'],true))$role='agent';$status=in_array($status,['active','inactive'],true)?$status:'active';$capacity=max(1,min(100,$capacity));$tenant=$this->tenantId();(new TalkTenantContext())->forUser($userId,$tenant);$pdo=Connection::getInstance();$q=$pdo->prepare('SELECT COUNT(*) FROM talk_queues WHERE tenant_id=:tenant_id AND id=:id');$q->execute(['tenant_id'=>$tenant,'id'=>$queueId]);if((int)$q->fetchColumn()===0)throw new \RuntimeException('Fila não encontrada.');$pdo->prepare("INSERT INTO talk_queue_members(tenant_id,queue_id,user_id,role,capacity,status) VALUES(:tenant_id,:queue_id,:user_id,:role,:capacity,:status) ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id),role=VALUES(role),capacity=VALUES(capacity),status=VALUES(status)")->execute(['tenant_id'=>$tenant,'queue_id'=>$queueId,'user_id'=>$userId,'role'=>$role,'capacity'=>$capacity,'status'=>$status]); }
    public function removeQueueMember(int $queueId,int $userId): void { Connection::getInstance()->prepare("DELETE FROM talk_queue_members WHERE tenant_id=:tenant_id AND queue_id=:queue_id AND user_id=:user_id")->execute(['tenant_id'=>$this->tenantId(),'queue_id'=>$queueId,'user_id'=>$userId]); }
    private function slug(string $value): string { $value=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value)?:$value;$value=strtolower(trim((string)preg_replace('/[^a-zA-Z0-9]+/','-',$value),'-'));return $value!==''?$value:'fila'; }
    private function queueSlugExists(string $slug): bool { $s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_queues WHERE tenant_id=:tenant_id AND slug=:slug");$s->execute(['tenant_id'=>$this->tenantId(),'slug'=>$slug]);return (int)$s->fetchColumn()>0; }

    public function claim(int $ticketId,int $userId): bool { $pdo=Connection::getInstance();$tenant=$this->tenantId();$pdo->beginTransaction();try{$permissions=$this->permissions($userId);if(($permissions['talk_role']??'none')==='none'){$pdo->rollBack();return false;}$active=$pdo->prepare("SELECT COUNT(*) FROM talk_tickets WHERE tenant_id=:tenant_id AND assigned_user_id=:user_id AND status IN ('assigned','open')");$active->execute(['tenant_id'=>$tenant,'user_id'=>$userId]);if((int)$active->fetchColumn()>=(int)$permissions['max_active_tickets']){$pdo->rollBack();return false;}$s=$pdo->prepare("SELECT id,queue_id,status FROM talk_tickets WHERE tenant_id=:tenant_id AND id=:id FOR UPDATE");$s->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$ticket=$s->fetch(PDO::FETCH_ASSOC);if(!$ticket||$ticket['status']!=='queued'){$pdo->rollBack();return false;}if($ticket['queue_id']!==null){$e=$pdo->prepare("SELECT COUNT(*) FROM talk_queue_members WHERE tenant_id=:tenant_id AND queue_id=:queue_id AND user_id=:user_id AND status='active'");$e->execute(['tenant_id'=>$tenant,'queue_id'=>$ticket['queue_id'],'user_id'=>$userId]);if((int)$e->fetchColumn()===0){$pdo->rollBack();return false;}}$u=$pdo->prepare("UPDATE talk_tickets SET assigned_user_id=:user_id,status='assigned',assigned_at=NOW(),last_activity_at=NOW(),updated_at=NOW() WHERE tenant_id=:tenant_id AND id=:id AND status='queued'");$u->execute(['tenant_id'=>$tenant,'user_id'=>$userId,'id'=>$ticketId]);if($u->rowCount()!==1){$pdo->rollBack();return false;}$pdo->prepare("INSERT INTO talk_events(tenant_id,ticket_id,user_id,actor_type,event_type,payload) VALUES(:tenant_id,:ticket_id,:user_id,'user','ticket.claimed',:payload)")->execute(['tenant_id'=>$tenant,'ticket_id'=>$ticketId,'user_id'=>$userId,'payload'=>json_encode(['assigned_user_id'=>$userId],JSON_THROW_ON_ERROR)]);$pdo->commit();return true;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }

    public function seedSimulation(int $actorId): int { $tenant=$this->tenantId();(new TalkTenantContext())->forUser($actorId,$tenant);$pdo=Connection::getInstance();$pdo->beginTransaction();try{$s=$pdo->prepare("INSERT IGNORE INTO talk_departments(tenant_id,name,slug,status) VALUES(:tenant_id,'Atendimento','atendimento','active')");$s->execute(['tenant_id'=>$tenant]);$s=$pdo->prepare("SELECT id FROM talk_departments WHERE tenant_id=:tenant_id AND slug='atendimento'");$s->execute(['tenant_id'=>$tenant]);$departmentId=(int)$s->fetchColumn();$q=$pdo->prepare("INSERT IGNORE INTO talk_queues(tenant_id,department_id,name,slug,status,auto_assign_after_seconds) VALUES(:tenant_id,:department_id,'Atendimento geral','atendimento-geral','active',30)");$q->execute(['tenant_id'=>$tenant,'department_id'=>$departmentId]);$q=$pdo->prepare("SELECT id FROM talk_queues WHERE tenant_id=:tenant_id AND slug='atendimento-geral'");$q->execute(['tenant_id'=>$tenant]);$queueId=(int)$q->fetchColumn();$ch=$pdo->prepare("SELECT id FROM talk_channels WHERE tenant_id=:tenant_id AND type='simulation' ORDER BY id LIMIT 1");$ch->execute(['tenant_id'=>$tenant]);$channelId=(int)$ch->fetchColumn();if($channelId<1){$ch=$pdo->prepare("INSERT INTO talk_channels(tenant_id,type,name,external_id,driver,status,connection_status) VALUES(:tenant_id,'simulation','Simulação','simulation-default','simulation','active','connected')");$ch->execute(['tenant_id'=>$tenant]);$channelId=(int)$pdo->lastInsertId();}$pdo->prepare("INSERT INTO talk_queue_members(tenant_id,queue_id,user_id,role,capacity,status) VALUES(:tenant_id,:queue_id,:user_id,'agent',5,'active') ON DUPLICATE KEY UPDATE tenant_id=VALUES(tenant_id),status='active'")->execute(['tenant_id'=>$tenant,'queue_id'=>$queueId,'user_id'=>$actorId]);$external='sim:'.bin2hex(random_bytes(6));$c=$pdo->prepare("INSERT INTO talk_contacts(tenant_id,channel_id,name,phone,external_id,channel,metadata) VALUES(:tenant_id,:channel_id,'Cliente de simulação','SIM-0001',:external_id,'simulation',:metadata)");$c->execute(['tenant_id'=>$tenant,'channel_id'=>$channelId,'external_id'=>$external,'metadata'=>json_encode(['simulation'=>true],JSON_THROW_ON_ERROR)]);$contactId=(int)$pdo->lastInsertId();$cv=$pdo->prepare("INSERT INTO talk_conversations(tenant_id,channel_id,contact_id,channel,external_id,status,last_message_at) VALUES(:tenant_id,:channel_id,:contact_id,'simulation',:external_id,'open',NOW())");$cv->execute(['tenant_id'=>$tenant,'channel_id'=>$channelId,'contact_id'=>$contactId,'external_id'=>$external.':conversation']);$conversationId=(int)$pdo->lastInsertId();$protocol='SIM-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$t=$pdo->prepare("INSERT INTO talk_tickets(tenant_id,channel_id,protocol,conversation_id,queue_id,status,priority,subject,source,queued_at) VALUES(:tenant_id,:channel_id,:protocol,:conversation_id,:queue_id,'queued','normal','Atendimento de simulação','simulation',NOW())");$t->execute(['tenant_id'=>$tenant,'channel_id'=>$channelId,'protocol'=>$protocol,'conversation_id'=>$conversationId,'queue_id'=>$queueId]);$ticketId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO talk_messages(tenant_id,channel_id,conversation_id,ticket_id,sender_type,direction,type,body,sent_at,metadata) VALUES(:tenant_id,:channel_id,:conversation_id,:ticket_id,'contact','inbound','text','Olá, preciso de ajuda com meu atendimento.',NOW(),:metadata)")->execute(['tenant_id'=>$tenant,'channel_id'=>$channelId,'conversation_id'=>$conversationId,'ticket_id'=>$ticketId,'metadata'=>json_encode(['simulation'=>true],JSON_THROW_ON_ERROR)]);$this->event($ticketId,$actorId,'ticket.created',['source'=>'simulation']);$pdo->commit();return $ticketId;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
    public function ticket(int $ticketId): ?array { $pdo=Connection::getInstance();$tenant=$this->tenantId();$s=$pdo->prepare("SELECT t.*,c.name contact_name,c.phone contact_phone,cv.channel,q.name queue_name,u.name assigned_name FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.tenant_id=t.tenant_id AND cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.tenant_id=t.tenant_id AND c.id=cv.contact_id LEFT JOIN talk_queues q ON q.tenant_id=t.tenant_id AND q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.tenant_id=:tenant_id AND t.id=:id LIMIT 1");$s->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$ticket=$s->fetch(PDO::FETCH_ASSOC);if(!$ticket)return null;$m=$pdo->prepare("SELECT m.*,u.name sender_name FROM talk_messages m LEFT JOIN users u ON u.id=m.sender_user_id WHERE m.tenant_id=:tenant_id AND m.ticket_id=:id ORDER BY m.sent_at,m.id");$m->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$e=$pdo->prepare("SELECT e.*,u.name user_name FROM talk_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.tenant_id=:tenant_id AND e.ticket_id=:id ORDER BY e.created_at DESC,e.id DESC LIMIT 50");$e->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$ticket['messages']=$m->fetchAll(PDO::FETCH_ASSOC);$ticket['events']=$e->fetchAll(PDO::FETCH_ASSOC);$ticket['notes']=$this->notes($ticketId);$ticket['queues']=$this->queues();$ticket['eligible_users']=$this->eligibleUsers($ticket['queue_id']!==null?(int)$ticket['queue_id']:null);return $ticket; }
    public function sendSimulationMessage(int $ticketId,int $userId,string $body): void { $body=trim($body);if($body==='')return;$ticket=$this->ticket($ticketId);if($ticket===null||$ticket['source']!=='simulation'||(int)($ticket['assigned_user_id']??0)!==$userId)throw new \RuntimeException('Atendimento de simulação indisponível para este usuário.');$pdo=Connection::getInstance();$tenant=$this->tenantId();$pdo->prepare("INSERT INTO talk_messages(tenant_id,channel_id,conversation_id,ticket_id,sender_type,sender_user_id,direction,type,body,sent_at,metadata) VALUES(:tenant_id,:channel_id,:conversation_id,:ticket_id,'user',:user_id,'outbound','text',:body,NOW(),:metadata)")->execute(['tenant_id'=>$tenant,'channel_id'=>$ticket['channel_id'],'conversation_id'=>$ticket['conversation_id'],'ticket_id'=>$ticketId,'user_id'=>$userId,'body'=>$body,'metadata'=>json_encode(['simulation'=>true],JSON_THROW_ON_ERROR)]);$pdo->prepare("UPDATE talk_tickets SET first_response_at=COALESCE(first_response_at,NOW()),last_activity_at=NOW(),updated_at=NOW() WHERE tenant_id=:tenant_id AND id=:id")->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$pdo->prepare("UPDATE talk_conversations SET last_message_at=NOW(),updated_at=NOW() WHERE tenant_id=:tenant_id AND id=:id")->execute(['tenant_id'=>$tenant,'id'=>$ticket['conversation_id']]); }
    public function myTickets(int $userId): array { $s=Connection::getInstance()->prepare("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.updated_at,c.name contact_name,c.phone contact_phone,q.name queue_name FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.tenant_id=t.tenant_id AND cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.tenant_id=t.tenant_id AND c.id=cv.contact_id LEFT JOIN talk_queues q ON q.tenant_id=t.tenant_id AND q.id=t.queue_id WHERE t.tenant_id=:tenant_id AND t.assigned_user_id=:user_id AND t.status IN ('assigned','open') ORDER BY t.updated_at DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId(),'user_id'=>$userId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function history(): array { $s=Connection::getInstance()->prepare("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.closed_at,t.updated_at,c.name contact_name,q.name queue_name,u.name assigned_name FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.tenant_id=t.tenant_id AND cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.tenant_id=t.tenant_id AND c.id=cv.contact_id LEFT JOIN talk_queues q ON q.tenant_id=t.tenant_id AND q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.tenant_id=:tenant_id AND t.status='closed' ORDER BY t.closed_at DESC,t.id DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function transfers(): array { $s=Connection::getInstance()->prepare("SELECT tr.*,t.protocol,fu.name from_user,tu.name to_user,fq.name from_queue,tq.name to_queue,cu.name created_by_name FROM talk_transfers tr INNER JOIN talk_tickets t ON t.tenant_id=tr.tenant_id AND t.id=tr.ticket_id LEFT JOIN users fu ON fu.id=tr.from_user_id LEFT JOIN users tu ON tu.id=tr.to_user_id LEFT JOIN talk_queues fq ON fq.tenant_id=tr.tenant_id AND fq.id=tr.from_queue_id LEFT JOIN talk_queues tq ON tq.tenant_id=tr.tenant_id AND tq.id=tr.to_queue_id LEFT JOIN users cu ON cu.id=tr.created_by WHERE tr.tenant_id=:tenant_id ORDER BY tr.created_at DESC,tr.id DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function queues(): array { $s=Connection::getInstance()->prepare("SELECT q.id,q.name,q.slug,q.status,q.auto_assign_after_seconds,d.name department_name,COUNT(qm.user_id) members FROM talk_queues q LEFT JOIN talk_departments d ON d.tenant_id=q.tenant_id AND d.id=q.department_id LEFT JOIN talk_queue_members qm ON qm.tenant_id=q.tenant_id AND qm.queue_id=q.id AND qm.status='active' WHERE q.tenant_id=:tenant_id GROUP BY q.id,d.name ORDER BY q.name");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function eligibleUsers(?int $queueId=null): array { if($queueId===null){$s=Connection::getInstance()->prepare("SELECT u.id,u.name,u.email,tu.role,u.status FROM talk_tenant_users tu INNER JOIN users u ON u.id=tu.user_id WHERE tu.tenant_id=:tenant_id AND tu.status='active' AND u.status='active' ORDER BY u.name");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC);}$s=Connection::getInstance()->prepare("SELECT u.id,u.name,u.email,qm.role,qm.capacity FROM talk_queue_members qm INNER JOIN users u ON u.id=qm.user_id WHERE qm.tenant_id=:tenant_id AND qm.queue_id=:queue_id AND qm.status='active' AND u.status='active' ORDER BY u.name");$s->execute(['tenant_id'=>$this->tenantId(),'queue_id'=>$queueId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function addNote(int $ticketId,int $userId,string $body): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); $body=trim($body);if($body==='')return;Connection::getInstance()->prepare("INSERT INTO talk_notes(tenant_id,ticket_id,user_id,body) VALUES(:tenant_id,:ticket_id,:user_id,:body)")->execute(['tenant_id'=>$this->tenantId(),'ticket_id'=>$ticketId,'user_id'=>$userId,'body'=>$body]);$this->event($ticketId,$userId,'ticket.note_added',['body'=>$body]); }
    public function notes(int $ticketId): array { $s=Connection::getInstance()->prepare("SELECT n.*,u.name user_name FROM talk_notes n LEFT JOIN users u ON u.id=n.user_id WHERE n.tenant_id=:tenant_id AND n.ticket_id=:id ORDER BY n.created_at DESC,n.id DESC");$s->execute(['tenant_id'=>$this->tenantId(),'id'=>$ticketId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function returnToQueue(int $ticketId,int $userId): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); $pdo=Connection::getInstance();$tenant=$this->tenantId();$s=$pdo->prepare("SELECT assigned_user_id FROM talk_tickets WHERE tenant_id=:tenant_id AND id=:id AND status IN ('assigned','open')");$s->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$previous=(int)$s->fetchColumn();$u=$pdo->prepare("UPDATE talk_tickets SET assigned_user_id=NULL,status='queued',queued_at=NOW(),assigned_at=NULL,updated_at=NOW() WHERE tenant_id=:tenant_id AND id=:id AND status IN ('assigned','open')");$u->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);if($u->rowCount()!==1)throw new \RuntimeException('Atendimento não pode retornar para a fila.');$this->event($ticketId,$userId,'ticket.returned_to_queue',[]);if($previous>0&&$previous!==$userId)$this->notifications()->notifyUser($previous,$ticketId,'ticket.returned_to_queue','Atendimento retornou para a fila','Um atendimento sob sua responsabilidade foi devolvido à fila.'); }
    public function close(int $ticketId,int $userId): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); $s=Connection::getInstance()->prepare("UPDATE talk_tickets SET status='closed',closed_at=NOW(),closed_by=:user_id,updated_at=NOW() WHERE tenant_id=:tenant_id AND id=:id AND status<>'closed'");$s->execute(['tenant_id'=>$this->tenantId(),'user_id'=>$userId,'id'=>$ticketId]);if($s->rowCount()!==1)throw new \RuntimeException('Atendimento já finalizado ou indisponível.');$this->event($ticketId,$userId,'ticket.closed',[]); }
