    public function transfer(int $ticketId,int $userId,?int $toUserId,?int $toQueueId,string $reason): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); if($toUserId===null&&$toQueueId===null)throw new \RuntimeException('Selecione um atendente ou uma fila.');$pdo=Connection::getInstance();$tenant=$this->tenantId();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT assigned_user_id,queue_id,status FROM talk_tickets WHERE tenant_id=:tenant_id AND id=:id FOR UPDATE");$s->execute(['tenant_id'=>$tenant,'id'=>$ticketId]);$t=$s->fetch(PDO::FETCH_ASSOC);if(!$t||!in_array($t['status'],['assigned','open'],true))throw new \RuntimeException('Atendimento indisponível para transferência.');$targetQueue=$toQueueId??(int)$t['queue_id'];$q=$pdo->prepare('SELECT COUNT(*) FROM talk_queues WHERE tenant_id=:tenant_id AND id=:id');$q->execute(['tenant_id'=>$tenant,'id'=>$targetQueue]);if((int)$q->fetchColumn()===0)throw new \RuntimeException('Fila selecionada não encontrada.');if($toUserId!==null){$e=$pdo->prepare("SELECT COUNT(*) FROM talk_queue_members WHERE tenant_id=:tenant_id AND queue_id=:queue_id AND user_id=:user_id AND status='active'");$e->execute(['tenant_id'=>$tenant,'queue_id'=>$targetQueue,'user_id'=>$toUserId]);if((int)$e->fetchColumn()===0)throw new \RuntimeException('Atendente não pertence à fila selecionada.');}$newStatus=$toUserId!==null?'assigned':'queued';$pdo->prepare("UPDATE talk_tickets SET queue_id=:queue_id,assigned_user_id=:assigned,status=:new_status,queued_at=IF(:queued_status='queued',NOW(),queued_at),assigned_at=IF(:assigned_status='assigned',NOW(),NULL),updated_at=NOW() WHERE tenant_id=:tenant_id AND id=:id")->execute(['tenant_id'=>$tenant,'queue_id'=>$targetQueue,'assigned'=>$toUserId,'new_status'=>$newStatus,'queued_status'=>$newStatus,'assigned_status'=>$newStatus,'id'=>$ticketId]);$pdo->prepare("INSERT INTO talk_transfers(tenant_id,ticket_id,from_user_id,from_queue_id,to_user_id,to_queue_id,reason,status,created_by) VALUES(:tenant_id,:ticket_id,:from_user,:from_queue,:to_user,:to_queue,:reason,'completed',:created_by)")->execute(['tenant_id'=>$tenant,'ticket_id'=>$ticketId,'from_user'=>$t['assigned_user_id'],'from_queue'=>$t['queue_id'],'to_user'=>$toUserId,'to_queue'=>$targetQueue,'reason'=>trim($reason),'created_by'=>$userId]);$pdo->commit();$this->event($ticketId,$userId,'ticket.transferred',['to_user_id'=>$toUserId,'to_queue_id'=>$targetQueue]);if($toUserId!==null&&$toUserId!==$userId)$this->notifications()->notifyUser($toUserId,$ticketId,'ticket.transferred','Novo atendimento transferido para você',trim($reason)!==''?trim($reason):'Abra o atendimento para continuar a conversa.',['from_user_id'=>$t['assigned_user_id'],'queue_id'=>$targetQueue]);if($t['assigned_user_id']!==null&&(int)$t['assigned_user_id']!==$userId&&(int)$t['assigned_user_id']!==$toUserId)$this->notifications()->notifyUser((int)$t['assigned_user_id'],$ticketId,'ticket.transferred_away','Atendimento transferido','O atendimento deixou sua responsabilidade.');}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
    public function autoAssign(): int { $settings=$this->settings();if(($settings['auto_assign.enabled']??'1')!=='1')return 0;$pdo=Connection::getInstance();$tenant=$this->tenantId();$s=$pdo->prepare("SELECT t.id,t.queue_id FROM talk_tickets t WHERE t.tenant_id=:tenant_id AND t.status='queued' AND t.queue_id IS NOT NULL AND TIMESTAMPDIFF(SECOND,COALESCE(t.queued_at,t.created_at),NOW())>=COALESCE((SELECT auto_assign_after_seconds FROM talk_queues q WHERE q.tenant_id=t.tenant_id AND q.id=t.queue_id),30) ORDER BY COALESCE(t.queued_at,t.created_at) LIMIT 50");$s->execute(['tenant_id'=>$tenant]);$tickets=$s->fetchAll(PDO::FETCH_ASSOC);$assigned=0;foreach($tickets as $ticket){$s=$pdo->prepare("SELECT qm.user_id FROM talk_queue_members qm INNER JOIN users u ON u.id=qm.user_id LEFT JOIN talk_presence p ON p.tenant_id=qm.tenant_id AND p.user_id=u.id LEFT JOIN talk_user_settings tus ON tus.tenant_id=qm.tenant_id AND tus.user_id=u.id LEFT JOIN (SELECT assigned_user_id,COUNT(*) active FROM talk_tickets WHERE tenant_id=:active_tenant AND status IN ('assigned','open') GROUP BY assigned_user_id) a ON a.assigned_user_id=u.id WHERE qm.tenant_id=:tenant_id AND qm.queue_id=:queue_id AND qm.status='active' AND u.status='active' AND p.status='online' AND p.last_seen_at>=DATE_SUB(NOW(),INTERVAL 5 MINUTE) AND COALESCE(a.active,0)<LEAST(qm.capacity,COALESCE(tus.max_active_tickets,qm.capacity)) ORDER BY COALESCE(a.active,0),p.last_seen_at DESC,qm.user_id LIMIT 1");$s->execute(['active_tenant'=>$tenant,'tenant_id'=>$tenant,'queue_id'=>$ticket['queue_id']]);$uid=(int)$s->fetchColumn();if($uid>0&&$this->claim((int)$ticket['id'],$uid)){$this->notifications()->notifyUser($uid,(int)$ticket['id'],'ticket.auto_assigned','Novo atendimento atribuído','Um atendimento da sua fila foi atribuído automaticamente a você.');$assigned++;}}return $assigned; }
    public function updatePresence(int $userId,string $status): void { if(!in_array($status,['online','away','offline'],true))$status='offline';(new TalkTenantContext())->forUser($userId,$this->tenantId());Connection::getInstance()->prepare("INSERT INTO talk_presence(tenant_id,user_id,status,last_seen_at) VALUES(:tenant_id,:user_id,:status,NOW()) ON DUPLICATE KEY UPDATE status=VALUES(status),last_seen_at=NOW()")->execute(['tenant_id'=>$this->tenantId(),'user_id'=>$userId,'status'=>$status]); }
    public function usersWithPresence(): array { $s=Connection::getInstance()->prepare("SELECT u.id,u.name,u.email,tu.role,u.status,COALESCE(tus.talk_role,tu.role,'agent') talk_role,COALESCE(tus.max_active_tickets,5) max_active_tickets,COALESCE(p.status,'offline') presence,p.last_seen_at,(SELECT COUNT(*) FROM talk_tickets t WHERE t.tenant_id=tu.tenant_id AND t.assigned_user_id=u.id AND t.status IN ('assigned','open')) active_tickets FROM talk_tenant_users tu INNER JOIN users u ON u.id=tu.user_id LEFT JOIN talk_user_settings tus ON tus.tenant_id=tu.tenant_id AND tus.user_id=u.id LEFT JOIN talk_presence p ON p.tenant_id=tu.tenant_id AND p.user_id=u.id WHERE tu.tenant_id=:tenant_id AND tu.status='active' AND u.status='active' ORDER BY u.name");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function reports(): array { $pdo=Connection::getInstance();$tenant=$this->tenantId();$p=['tenant_id'=>$tenant];$count=function(string $sql)use($pdo,$p):int{$s=$pdo->prepare($sql);$s->execute($p);return (int)$s->fetchColumn();};$s=$pdo->prepare("SELECT COALESCE(q.name,'Sem fila') label,COUNT(t.id) total FROM talk_tickets t LEFT JOIN talk_queues q ON q.tenant_id=t.tenant_id AND q.id=t.queue_id WHERE t.tenant_id=:tenant_id GROUP BY q.id,q.name ORDER BY total DESC");$s->execute($p);return ['total'=>$count("SELECT COUNT(*) FROM talk_tickets WHERE tenant_id=:tenant_id"),'queued'=>$count("SELECT COUNT(*) FROM talk_tickets WHERE tenant_id=:tenant_id AND status='queued'"),'active'=>$count("SELECT COUNT(*) FROM talk_tickets WHERE tenant_id=:tenant_id AND status IN ('assigned','open')"),'closed'=>$count("SELECT COUNT(*) FROM talk_tickets WHERE tenant_id=:tenant_id AND status='closed'"),'by_queue'=>$s->fetchAll(PDO::FETCH_ASSOC)]; }
    public function settings(): array { $s=Connection::getInstance()->prepare("SELECT setting_key,setting_value FROM talk_settings WHERE tenant_id=:tenant_id ORDER BY setting_key");$s->execute(['tenant_id'=>$this->tenantId()]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$out=[];foreach($rows as $row)$out[$row['setting_key']]=$row['setting_value'];return $out; }
    public function saveSettings(array $values,int $userId): void { if(!$this->canManage($userId))throw new \RuntimeException('Somente gestores podem alterar configurações.');$allowed=['jack.enabled','jack.wait_seconds','jack.transfer_summary','auto_assign.enabled','auto_assign.default_seconds'];$s=Connection::getInstance()->prepare("INSERT INTO talk_settings(tenant_id,setting_key,setting_value,updated_by) VALUES(:tenant_id,:key,:value,:user_id) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)");foreach($allowed as $key)if(array_key_exists($key,$values))$s->execute(['tenant_id'=>$this->tenantId(),'key'=>$key,'value'=>(string)$values[$key],'user_id'=>$userId]); }
    public function jackInteractions(): array { $s=Connection::getInstance()->prepare("SELECT ji.*,t.protocol,c.name contact_name FROM talk_jack_interactions ji INNER JOIN talk_tickets t ON t.tenant_id=ji.tenant_id AND t.id=ji.ticket_id INNER JOIN talk_conversations cv ON cv.tenant_id=t.tenant_id AND cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.tenant_id=t.tenant_id AND c.id=cv.contact_id WHERE ji.tenant_id=:tenant_id ORDER BY ji.created_at DESC,ji.id DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function channels(): array { $s=Connection::getInstance()->prepare("SELECT id,type,name,external_id,driver,status,connection_status,phone_number,last_connected_at,last_error,created_at,updated_at FROM talk_channels WHERE tenant_id=:tenant_id ORDER BY id");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    private function event(int $ticketId,?int $userId,string $type,array $payload): void { $s=Connection::getInstance()->prepare("INSERT INTO talk_events(tenant_id,ticket_id,user_id,actor_type,event_type,payload) VALUES(:tenant_id,:ticket_id,:user_id,:actor_type,:event_type,:payload)");$s->execute(['tenant_id'=>$this->tenantId(),'ticket_id'=>$ticketId,'user_id'=>$userId,'actor_type'=>$userId===null?'system':'user','event_type'=>$type,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR)]); }
    public function syncState(int $userId): array
    {
        $pdo=Connection::getInstance();$params=['tenant_id'=>$this->tenantId()];
        if($this->canManage($userId)){
            $ticketSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(updated_at)),0) FROM talk_tickets WHERE tenant_id=:tenant_id";
            $messageSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(created_at)),0) FROM talk_messages WHERE tenant_id=:tenant_id";
        }else{
            $ticketSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(updated_at)),0) FROM talk_tickets WHERE tenant_id=:tenant_id AND (assigned_user_id=:user_id OR status='queued')";
            $messageSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(m.created_at)),0) FROM talk_messages m INNER JOIN talk_tickets t ON t.tenant_id=m.tenant_id AND t.id=m.ticket_id WHERE m.tenant_id=:tenant_id AND (t.assigned_user_id=:user_id OR t.status='queued')";
            $params['user_id']=$userId;
        }
        $s=$pdo->prepare($ticketSql);$s->execute($params);$tickets=(int)$s->fetchColumn();
        $s=$pdo->prepare($messageSql);$s->execute($params);$messages=(int)$s->fetchColumn();
        return ['revision'=>max($tickets,$messages),'server_time'=>time()];
    }
    public function conversations(string $search=''): array { $search=trim($search);$sql="SELECT cv.id,cv.channel,cv.status,cv.last_message_at,c.name contact_name,c.phone,t.id ticket_id,t.protocol,t.status ticket_status,q.name queue_name,u.name assigned_name,(SELECT m.body FROM talk_messages m WHERE m.tenant_id=cv.tenant_id AND m.conversation_id=cv.id ORDER BY COALESCE(m.sent_at,m.created_at) DESC,m.id DESC LIMIT 1) last_message_preview,(SELECT COUNT(*) FROM talk_messages um WHERE um.tenant_id=cv.tenant_id AND um.ticket_id=t.id AND um.direction='inbound' AND um.read_at IS NULL) unread_count FROM talk_conversations cv INNER JOIN talk_contacts c ON c.tenant_id=cv.tenant_id AND c.id=cv.contact_id LEFT JOIN talk_tickets t ON t.tenant_id=cv.tenant_id AND t.id=(SELECT tt.id FROM talk_tickets tt WHERE tt.tenant_id=cv.tenant_id AND tt.conversation_id=cv.id ORDER BY tt.id DESC LIMIT 1) LEFT JOIN talk_queues q ON q.tenant_id=cv.tenant_id AND q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE cv.tenant_id=:tenant_id";$params=['tenant_id'=>$this->tenantId()];if($search!==''){$sql.=" AND (c.name LIKE :search_name OR c.phone LIKE :search_phone OR t.protocol LIKE :search_protocol)";$like='%'.$search.'%';$params['search_name']=$like;$params['search_phone']=$like;$params['search_protocol']=$like;}$sql.=" ORDER BY COALESCE(cv.last_message_at,cv.created_at) DESC,cv.id DESC LIMIT 100";$statement=Connection::getInstance()->prepare($sql);$statement->execute($params);return $statement->fetchAll(PDO::FETCH_ASSOC); }
    public function markTicketRead(int $ticketId): void { $statement=Connection::getInstance()->prepare("UPDATE talk_messages SET read_at=NOW() WHERE tenant_id=:tenant_id AND ticket_id=:ticket_id AND direction='inbound' AND read_at IS NULL");$statement->execute(['tenant_id'=>$this->tenantId(),'ticket_id'=>$ticketId]); }
    public function contacts(): array { $s=Connection::getInstance()->prepare("SELECT id,name,phone,email,channel,created_at,updated_at FROM talk_contacts WHERE tenant_id=:tenant_id ORDER BY updated_at DESC,id DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId()]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    private function count(PDO $pdo,string $sql): int { return (int)$pdo->query($sql)->fetchColumn(); }
